insert into news (id, slug, title_en, title_ka, excerpt_en, excerpt_ka, body_en, body_ka, sport_id, university_id, published_at, is_announcement, read_minutes, image_url) values
  ('football-season-opens', 'football-season-opens', 'The football season is back', 'ფეხბურთის სეზონი ბრუნდება', 'Entries for the BTU Football League open on 1 November; the first whistle follows on 15 November.', 'BTU-ს ფეხბურთის ლიგაზე რეგისტრაცია 1 ნოემბერს იხსნება, პირველი სასტვენი კი 15 ნოემბერს გაისმის.', 'The federation league returns with five groups of five and a knockout play-off to decide the title. Squads of six to nine enter for 210 GEL, and the window runs from 1 to 10 November — the draw is made once it closes. Matches are played at the BTU campus pitch through to 20 December, and the regulations are published on the entry page.', 'ფედერაციის ლიგა ბრუნდება ხუთი ხუთგუნდიანი ჯგუფით და ნოკაუტ პლეიოფით, რომელიც ტიტულს გადაწყვეტს. ექვსიდან ცხრა მოთამაშემდე შემადგენლობები 210 ლარად რეგისტრირდებიან, ფანჯარა კი 1-დან 10 ნოემბრამდეა ღია — ბადე მის დახურვისთანავე გათამაშდება. მატჩები BTU-ს კამპუსის მოედანზე 20 დეკემბრამდე გაგრძელდება, რეგლამენტი კი რეგისტრაციის გვერდზეა გამოქვეყნებული.', 'football', 'btu', '2026-10-22T10:00:00+04:00', true, 2, '/gallery/match-2.webp'),
  ('padel-cup-opens', 'padel-cup-opens', 'The padel cup takes over the weekend', 'პადელის თასი შაბათ-კვირას იბარებს', 'Sixteen pairs, straight knockout, played across 12 and 13 November at Padel Park Saburtalo.', 'თექვსმეტი წყვილი, პირდაპირი ნოკაუტი, 12 და 13 ნოემბერს პადელ პარკ საბურთალოზე.', 'The BTU Padel Cup is a straight knockout over two days on four courts — lose once and your weekend is over. Pairs enter for 160 GEL between 1 and 10 November, and both players give their name, email, phone and photo on the entry form. Sixteen places only, so the draw fills quickly.', 'BTU-ს პადელის თასი ორდღიანი პირდაპირი ნოკაუტია ოთხ კორტზე — ერთი მარცხი და შაბათ-კვირა დასრულდა. წყვილები 160 ლარად რეგისტრირდებიან 1-დან 10 ნოემბრამდე, ორივე მოთამაშე კი ფორმაში უთითებს სახელს, ელფოსტას, ტელეფონსა და ფოტოს. ადგილები მხოლოდ თექვსმეტია, ამიტომ ბადე სწრაფად ივსება.', 'padel', 'btu', '2026-10-20T12:00:00+04:00', true, 2, '/gallery/padel-3.webp'),
  ('welcome-party-recap', 'welcome-party-sold-out', 'The Welcome Party sold out', 'ველქამ ფართი წარმატებით ჩატარდა', 'Every ticket went before the doors opened, and Tsameti stayed full until six in the morning.', 'ყველა ბილეთი კარის გაღებამდე გაიყიდა, ცამეტი კი დილის ექვს საათამდე სავსე იყო.', 'The students’ welcome party filled Tsameti on 11 October and sold out before the night began. TOBIASS opened at half nine, TAMTA took midnight to two, and LOMJ carried it through to six. Thanks to everyone who came — the next one is already being planned, and it will be announced here first.', 'სტუდენტების ველქამ ფართმა 11 ოქტომბერს ცამეტი აავსო და ბილეთები ღამის დაწყებამდე გაიყიდა. TOBIASS ცხრანახევარზე გაუშვა, TAMTA შუაღამიდან ორამდე დადგა, LOMJ-მა კი ექვსამდე მიიყვანა. მადლობა ყველას, ვინც მოხვედით — შემდეგი უკვე იგეგმება და პირველად აქ გამოცხადდება.', null, 'btu', '2026-10-12T14:00:00+04:00', false, 2, '/events/welcome-party-2026.webp')
on conflict (id) do update set
